const manuals={label:"Chevrolet owner manuals and guides",url:"https://experience.gm.com/support/vehicle/manuals-guides",note:"Official GM model-year and VIN manual lookup; use VIN-correct service information for diagnostic specifications"};
const cac={label:"GM Bulletin 18-NA-020 — Equinox charge-air-cooler moisture",url:"https://static.nhtsa.gov/odi/tsbs/2022/MC-10213487-0001.pdf",note:"2018–2022 Equinox 1.5L LYX and 2.0L LTG guidance for P0300/P0299/P0234/P2227; repair depends on leakage, build and climate"};
const dieselCac={label:"GM Bulletin 20-NA-103 — 1.6L diesel charge-air moisture",url:"https://static.nhtsa.gov/odi/tsbs/2020/MC-10176636-9999.pdf",note:"2018–2020 Equinox 1.6L LH7 P0300 after long wet or humid driving; grille-cover limits and towing/temperature warnings apply"};
const piston={label:"GM PI1178F — 2.0L LTG low compression with P0300",url:"https://static.nhtsa.gov/odi/tsbs/2018/MC-10155075-9999.pdf",note:"2018 Equinox 2.0L LTG guidance requiring leak-down confirmation when a cylinder has low compression"};
const p1101old={label:"GM PIP5402C — 2018 Equinox P1101 charge-air seal",url:"https://static.nhtsa.gov/odi/tsbs/2017/MC-10157043-9999.pdf",note:"2018 Equinox 1.5L LYX/2.0L LTG guidance to inspect the charge-air-cooler coupler O-ring after normal SI diagnosis"};
const p1101new={label:"GM PIP5927B — 2023–2025 Equinox charge-air inlet hose",url:"https://static.nhtsa.gov/odi/tsbs/2024/MC-11008980-0001.pdf",note:"2023–2025 Equinox 1.5L LSD guidance for P1101/P0101/P0237/P0299 and possible hose damage beneath the abrasion sleeve"};
