const p0521={label:"GM Bulletin 18-NA-246 — P0521/P06DE oil and PCV procedure",url:"https://static.nhtsa.gov/odi/tsbs/2022/MC-10209255-0001.pdf",note:"Defined Equinox applications and build breakpoints; procedure can involve calibration, PCV service and an oil/filter change rather than automatic sensor replacement"};
