const vehicle={name:"Chevrolet Equinox",kicker:"CHEVROLET EQUINOX · ENGINE AND EMISSIONS DIAGNOSTICS",breadcrumb:"Chevrolet Equinox",about:"Chevrolet Equinox trouble-code diagnosis",yearsIntro:"Equinox spans several unrelated powertrains: early V6s, the second-generation 2.4L and 3.0/3.6L engines, 2018-and-newer turbo gasoline engines, and a 1.6L diesel. Code definitions may be shared, but test values, component locations, failure patterns and bulletins are not. Identify model year, VIN and engine RPO before applying a repair."};
type Input=Omit<TroubleCodeGuide,"slug"|"vehicle"|"yearNotes"|"sources"|"deepDive"|"closing">&{slug:string;yearNotes:string[];sources?:TroubleCodeGuide["sources"];deepDive?:NonNullable<TroubleCodeGuide["deepDive"]>};

function guide(x:Input):TroubleCodeGuide{return{...x,slug:`chevrolet/equinox/${x.slug}`,vehicle,yearNotes:[...x.yearNotes,"Confirm model year, engine displacement and RPO from the emissions label or VIN catalog. Do not transfer a 2.4L procedure to a 1.5L turbo, 2.0L turbo, V6 or diesel.","Check every bulletin's model, year, RPO and build breakpoint. A bulletin is a diagnostic lead for a defined population, not proof of a failed part.","Record modifications, recent engine work, collision repairs, battery events and calibration history because each can change the diagnostic starting point."],deepDive:[...(x.deepDive??[]),{heading:`Reading an Equinox scan report for ${x.code}`,paragraphs:[`Save confirmed, pending and permanent codes, readiness and the first freeze frame before clearing ${x.code}. Coolant temperature, rpm, load, speed, fuel level and time since start tell you whether the monitor failed during cold start, warm idle, highway operation, deceleration or refueling. Testing in a different state can make a real intermittent fault appear normal.`,`Read companion codes as a system. A circuit or five-volt-reference code moves wiring tests ahead of component replacement. Misfire or mixture faults must be corrected before catalyst efficiency is judged. On turbo engines, P0299, P0234, P0101 or pressure-sensor codes can turn an apparently isolated fault into an induction-system diagnosis.`,`Graph related PIDs on the same time scale and label units. Compare commanded with actual values and look for a change at the failure moment rather than judging a single warm-idle number. Cold temperature sensors should begin near ambient after an overnight soak.`]},{heading:"What an owner can check—and where to stop",paragraphs:["With the engine cold, an owner can inspect oil and coolant levels, the air-filter housing, intake and charge pipes, battery terminals, accessible grounds, EVAP hoses and connectors disturbed during recent work. Photograph the original condition and avoid unplugging several components at once.","Professional equipment is appropriate for regulated EVAP smoke, bidirectional purge/vent or throttle commands, charge-air pressure testing, oscilloscope cam/crank correlation, mechanical oil-pressure measurement, fuel-pressure work, compression/leak-down and catalyst testing. Turbo plumbing can contain hot oil residue and pressurized air; fuel vapor and moving throttle plates add separate hazards.","Ask the repairer which test failed, under what conditions and which RPO-specific procedure was used. A line reading only ‘code present—replace component’ does not distinguish the component from its wiring, plumbing, calibration or the upstream fault that damaged it."]},{heading:"Using GM bulletins without overdiagnosing",paragraphs:["Match the VIN application before treating a GM document as relevant. An Equinox bulletin may cover only one engine, one build period or one weather pattern. Similar symptoms on another generation still require the normal Service Information diagnostic tree.","Follow the sequence in the document. Several Equinox bulletins apply only after ordinary SI checks fail, and some explicitly warn against automatic assembly replacement. Preserve those conditions in the estimate instead of turning a possible cause into a verdict.","Warranty, recall and special-coverage status are separate from technical relevance. Verify current VIN status with Chevrolet or NHTSA; do not promise free repair merely because a public bulletin describes a similar vehicle."]},{heading:"Repair verification",paragraphs:[`Clear ${x.code} only after saving the original evidence and repairing a proven cause. Reinspect every disturbed seal, clamp, connector and fluid level, then monitor the relevant data at idle before attempting a road test.`,`Repeat the safe portion of the freeze-frame condition. A turbo moisture fault may require climate-specific reasoning; an EVAP monitor needs the correct fuel level and soak; a catalyst monitor will not be meaningful while misfire or fuel control remains abnormal.`,`Check pending codes after the drive and allow readiness to progress without repeated resets. Permanent codes disappear after the vehicle completes enough passing monitor operation, not because the battery was disconnected. Keep before-and-after reports.`]}],closing:{title:`When the ${x.code} repair is actually complete`,paragraphs:[`The repair is complete when the original operating condition is reproduced safely, the monitored values behave normally and no pending ${x.code} or related fault returns. Turning off the lamp or clearing memory alone proves nothing.`,`Recheck for oil, fuel, vapor, coolant or boost leaks and inspect anything moved during testing. If the original condition cannot be reproduced because weather, fuel level or temperature changed, document that limitation and continue monitoring rather than claiming certainty.`,`If the code returns, compare the new freeze frame with the first. The same pattern suggests an incomplete root-cause repair; a different load, temperature or companion-code pattern may reveal a second fault.`]},sources:[...(x.sources??[]),manuals]};}

const commonFreeze=["Confirmed, pending and permanent codes","RPM, load, coolant and intake temperature","Vehicle speed and time since start","Battery voltage and relevant five-volt reference","Companion codes and recent repair history","Relevant commanded-versus-actual PIDs"];

export const troubleCodeEquinox:TroubleCodeGuide[]=[
guide({slug:"p0300",code:"P0300",title:"P0300 Code Chevy Equinox: Misfire Causes by Engine and Year",description:"Diagnose Chevy Equinox P0300 using cylinder counts, plugs, coils, fuel data, compression and engine-specific GM charge-air moisture guidance.",definition:"Engine Misfire Detected",severity:"Stop soon",driveAdvice:"Stop for a flashing lamp, strong shaking, raw-fuel odor, overheating, low oil pressure or mechanical noise. An active misfire can overheat the catalyst. Do not use heavy boost or continue a highway pull merely to reproduce it.",quickAnswer:"P0300 means the ECM detected crankshaft-speed variation consistent with misfire but did not assign the fault to one cylinder. On an Equinox, engine identity changes the shortlist: ordinary ignition, injector, air and compression faults remain possible, while defined turbo/diesel applications also have GM guidance for charge-air-cooler moisture. Use cylinder counters and freeze frame before touching parts.",symptoms:[{key:"flash",label:"Lamp flashes and engine shakes",response:"Stop load immediately and identify the cylinders accumulating misfire."},{key:"wet",label:"Appeared after humid, rainy or freezing highway use",response:"On a covered turbo/diesel application, inspect charge-air moisture and follow the exact GM bulletin."},{key:"one",label:"One cylinder leads",response:"Inspect its plug/coil/injector and prove compression before system-wide parts."},{key:"cold",label:"Cold-start misfire",response:"Save counts immediately; check plug condition, injector leakage and sealing."},{key:"boost",label:"Misfire under boost",response:"Inspect ignition reserve, fuel pressure and the complete charge-air path."}],causes:[{cause:"Worn/fouled plug or weak coil",evidence:"Counter or fault follows controlled swap",firstTest:"Inspect plugs in cylinder order and move one known-good coil"},{cause:"Charge-air moisture/leak on covered turbo engine",evidence:"Weather/highway pattern or boost companion codes",firstTest:"Smoke-test charge-air system and match GM bulletin"},{cause:"Injector or fuel-pressure fault",evidence:"Ignition passes; pressure/contribution abnormal",firstTest:"Graph pressure and perform RPO-correct injector test"},{cause:"Air/PCV leak",evidence:"Positive trims strongest at idle",firstTest:"Smoke-test sealed induction system"},{cause:"Low compression/piston/valve/timing fault",evidence:"Fixed cylinder, noise or low relative compression",firstTest:"Relative compression followed by leak-down"}],freezeFrame:[...commonFreeze,"Cylinder-specific misfire counters","Fuel trims and commanded/actual pressure","Weather and length of highway operation"],steps:[{title:"Preserve the misfire pattern",detail:"Save counters, freeze frame and all companion codes."},{title:"Identify the engine and weather context",detail:"Match RPO and determine whether a charge-air bulletin could apply."},{title:"Separate one cylinder from a system fault",detail:"Compare counters and both-bank or global fuel control."},{title:"Test ignition without a parts cannon",detail:"Read plugs and perform one controlled coil test."},{title:"Prove fuel, air and compression",detail:"Use pressure, smoke and mechanical tests as evidence directs."},{title:"Repeat the setting condition safely",detail:"Confirm counters stay stable and no pending code returns."}],dontReplace:"Do not install a full set of coils because P0300 says misfire, and do not install a charge-air cooler solely because a bulletin exists. Establish the cylinder/system pattern, leak status, engine RPO, build date and weather conditions first.",yearNotes:["2018–2022 1.5L LYX/2.0L LTG: 18-NA-020 addresses defined charge-air moisture conditions.","2018–2020 1.6L LH7 diesel: 20-NA-103 covers moisture ingestion after long wet/humid driving and specifies grille-cover limits.","2018 2.0L LTG with low compression: PI1178F requires leak-down evidence before its piston repair path."],faqs:[{question:"Can I drive with P0300?",answer:"Not with a flashing lamp or severe symptoms; catalyst damage can occur quickly."},{question:"Does it mean bad coils?",answer:"No. Fuel, air, compression, timing and charge-air moisture can cause it."},{question:"How do I identify the cylinder?",answer:"Read live/Mode $06 cylinder counters and pending P0301–P0304/P0306 codes."},{question:"Can weather cause it?",answer:"GM documents charge-air moisture on specific turbo and diesel applications, not every Equinox."},{question:"Should I clear it first?",answer:"No. Preserve freeze frame and counters first."},{question:"Can a cracked piston cause it?",answer:"GM documents a defined 2018 2.0L case, but leak-down must confirm leakage."},{question:"Will plugs fix it?",answer:"Only when inspection and testing prove plug wear or fouling."},{question:"What confirms repair?",answer:"Stable counters and no pending return under the original condition."}],sources:[cac,dieselCac,piston]}),
guide({slug:"p0171",code:"P0171",title:"P0171 Code Chevy Equinox: Lean Mixture Diagnostic Guide",description:"Diagnose Equinox P0171 with fuel trims, intake and charge-air smoke testing, purge checks, exhaust inspection and fuel-pressure data.",definition:"Fuel Trim System Lean",severity:"Diagnose promptly",driveAdvice:"Avoid hard acceleration until mixture and fuel pressure are verified. Stop for flashing misfire, detonation, sharp power loss or overheating. A smooth engine with a steady lamp may allow a short diagnostic trip.",quickAnswer:"P0171 means the ECM has added more fuel correction than its calibrated lean limit allows. It does not say the oxygen sensor failed. Compare trims at idle and higher airflow, then test unmetered intake/charge air, purge flow, exhaust leakage, measured airflow and commanded-versus-actual fuel pressure for the exact engine.",symptoms:[{key:"idle",label:"Trim highest at idle",response:"Smoke-test intake, PCV and brake-booster plumbing."},{key:"load",label:"Worse under boost/load",response:"Pressure-test charge pipes and graph fuel delivery."},{key:"refuel",label:"Rough after refueling",response:"Test purge sealing rather than guessing."},{key:"cold",label:"Cold-only",response:"Check gasket leakage and temperature-sensor plausibility."},{key:"codes",label:"P0101/P1101/P0299 also set",response:"Treat the induction/charge-air system as one diagnosis."}],causes:[{cause:"Intake, PCV or charge-air leak",evidence:"Idle/load pattern or smoke escape",firstTest:"Smoke/pressure test the correct side of turbo"},{cause:"Purge valve leaking",evidence:"Flow when commanded closed/post-refuel symptom",firstTest:"Bidirectional seal test"},{cause:"Low fuel pressure or injector delivery",evidence:"Trim rises with demand; pressure lags",firstTest:"Graph commanded versus actual pressure"},{cause:"Exhaust leak before upstream sensor",evidence:"Cold tick/soot and false oxygen",firstTest:"Inspect cold and leak-test safely"},{cause:"Biased MAF/MAP/O2 input",evidence:"PID fails plausibility/controlled response",firstTest:"Prove only after physical leaks and fuel pass"}],freezeFrame:[...commonFreeze,"Short- and long-term trims","MAF/MAP and boost pressure","Purge command and fuel pressure"],steps:[{title:"Save trims and context",detail:"Do not clear the idle/load pattern."},{title:"Identify the engine",detail:"Map naturally aspirated versus turbo plumbing."},{title:"Compare idle with higher airflow",detail:"Use the change to prioritize air versus delivery."},{title:"Smoke-test and test purge",detail:"Use regulated equipment and commanded sealing."},{title:"Verify fuel, exhaust and sensors",detail:"Test rather than infer from the code label."},{title:"Confirm correction",detail:"Repeat the original condition and inspect pending codes."}],dontReplace:"Do not replace the upstream oxygen sensor because it reports lean. A correct sensor often reports air, purge or fuel-delivery faults accurately.",yearNotes:["2010–2017 2.4L uses different PCV, intake and fuel architecture from 2018+ turbo engines.","On 2018+ turbo engines, test charge-air ducts and couplers as well as vacuum-side plumbing."],faqs:[{question:"What does P0171 mean?",answer:"Fuel correction exceeded the ECM's lean limit."},{question:"Is the oxygen sensor bad?",answer:"Not necessarily; it often reports the real mixture correctly."},{question:"Can a vacuum leak cause it?",answer:"Yes, especially when trim is highest at idle."},{question:"Can a boost leak cause it?",answer:"It can on turbo applications; interpret it with airflow and pressure data."},{question:"Can purge cause it?",answer:"Yes when vapor flow occurs with the valve commanded closed."},{question:"Can I keep driving?",answer:"Avoid load and diagnose promptly; stop for misfire or power loss."},{question:"What data matters most?",answer:"Trim by operating state, airflow, pressure, purge and companion codes."},{question:"What proves repair?",answer:"Normal correction and no pending lean fault in the original condition."}]}),
guide({slug:"p0420",code:"P0420",title:"P0420 Code Chevy Equinox: Catalyst Tests Before Replacement",description:"Diagnose Equinox P0420 by repairing misfire and mixture faults first, checking exhaust leaks, validating sensors and testing catalyst efficiency.",definition:"Catalyst System Low Efficiency Bank 1",severity:"Service soon",driveAdvice:"A steady P0420 alone often permits limited driving, but stop for flashing misfire, raw-fuel odor, glowing exhaust, overheating or major power loss. Those conditions can destroy or overheat the converter.",quickAnswer:"P0420 means the catalyst monitor judged Bank 1 oxygen-storage performance below threshold. It does not identify the original cause. Misfire, rich/lean control, oil consumption, coolant entry, exhaust leakage, sensor/circuit error and an incorrect replacement converter must be resolved before condemning the catalyst.",symptoms:[{key:"alone",label:"P0420 only",response:"Inspect leaks and execute the RPO-specific catalyst test."},{key:"misfire",label:"Misfire codes present",response:"Repair them before evaluating catalyst efficiency."},{key:"oil",label:"Oil use or blue smoke",response:"Diagnose contamination source before fitting a converter."},{key:"rattle",label:"Rattle or power restriction",response:"Avoid load and test substrate/backpressure."},{key:"return",label:"Returned after converter replacement",response:"Verify certification, sensors, leaks and upstream root cause."}],causes:[{cause:"Aged or damaged catalyst",evidence:"Monitor fails after all upstream faults pass",firstTest:"Run SI catalyst efficiency procedure"},{cause:"Misfire or mixture damage",evidence:"Counters, trims or companion codes abnormal",firstTest:"Correct engine control first"},{cause:"Exhaust leak",evidence:"Soot/tick/smoke ahead of sensors",firstTest:"Inspect cold and leak-test"},{cause:"Oil/coolant contamination",evidence:"Consumption/deposits/fluid loss",firstTest:"Find internal source"},{cause:"Sensor, wiring or wrong converter",evidence:"Implausible response or repair history",firstTest:"Circuit/response and emissions-part verification"}],freezeFrame:[...commonFreeze,"Upstream/downstream sensor graphs","Misfire counters and trims","Oil/coolant consumption history"],steps:[{title:"Save the full report",detail:"Record monitor state and companion faults."},{title:"Fix active engine faults",detail:"Misfire and mixture diagnosis comes first."},{title:"Inspect exhaust integrity",detail:"Find leakage before interpreting oxygen storage."},{title:"Validate sensor operation",detail:"Use controlled response and circuit tests."},{title:"Run catalyst procedure",detail:"Meet enable conditions and use VIN-correct thresholds."},{title:"Protect the repair",detail:"Correct contamination and verify monitor completion."}],dontReplace:"Do not install a converter based on one code or on similar-looking sensor waves alone. Prove the monitor result after upstream faults, leaks and sensor circuits pass.",yearNotes:["Single-bank inline-four applications still use the phrase Bank 1 in the generic definition.","Federal and California emissions certification can require different legal replacement converters; match the underhood label."],faqs:[{question:"Does P0420 always mean a bad converter?",answer:"No. Upstream engine, leak and sensor faults can create or damage it."},{question:"Can misfire cause it?",answer:"Yes, and active misfire must be repaired first."},{question:"Can oil burning ruin a converter?",answer:"Yes. Correct the consumption source before replacement."},{question:"Can I drive?",answer:"Usually briefly if alone and smooth; stop for overheating or flashing misfire."},{question:"Will an oxygen sensor fix it?",answer:"Only when testing proves sensor/circuit failure."},{question:"Can an exhaust leak set it?",answer:"Yes, particularly ahead of or near the monitored sensors."},{question:"Does clearing fix it?",answer:"No; it resets evidence and monitor readiness."},{question:"What confirms repair?",answer:"Normal upstream systems and a completed catalyst monitor without a pending return."}]}),
guide({slug:"p0016",code:"P0016",title:"P0016 Code Chevy Equinox: Cam-Crank Correlation Diagnosis",description:"Diagnose Equinox P0016 with oil checks, cam command/actual data, actuator tests, waveform correlation and 2.4L cam-reluctor bulletin boundaries.",definition:"Crankshaft Position–Intake Camshaft Position Correlation",severity:"Diagnose promptly",driveAdvice:"Stop for rattling, low oil pressure, stalling or a crank-no-start. Do not repeatedly crank an engine with mechanical timing noise. A smooth engine with a steady lamp still needs prompt diagnosis.",quickAnswer:"P0016 means the ECM found the intake-cam signal out of its expected relationship with the crank signal. Low/incorrect oil, a sticking actuator or solenoid, wiring, sensor indexing, chain/tensioner wear, incorrect assembly and a shifted reluctor are different faults requiring different evidence. On covered 2010–2016 2.4L engines, GM PIP4548E discusses reluctor movement only after timing and SI checks.",symptoms:[{key:"noise",label:"Rattle at start",response:"Check oil pressure/condition and mechanical timing before driving."},{key:"nostart",label:"Crank-no-start",response:"Avoid repeated cranking; verify correlation and compression."},{key:"after",label:"Began after timing work",response:"Recheck timing marks, reluctors, connectors and fastener procedure."},{key:"hot",label:"Appears hot or after overheat",response:"On covered 2.4L, consider reluctor evidence after base timing passes."},{key:"codes",label:"P0017/P0011/P0014 also set",response:"Diagnose shared oil/VVT/timing evidence together."}],causes:[{cause:"Low, dirty or wrong-viscosity oil",evidence:"Level/condition/history abnormal",firstTest:"Verify cold level and correct specification"},{cause:"VVT solenoid/actuator or oil passage fault",evidence:"Commanded and actual cam response differ",firstTest:"Circuit, command and oil-flow tests"},{cause:"Chain, guide or tensioner wear",evidence:"Noise/phase error/mechanical evidence",firstTest:"Correlation waveform and mechanical inspection"},{cause:"Incorrect timing after repair",evidence:"Code began immediately after service",firstTest:"Recheck SI timing procedure"},{cause:"Shifted cam reluctor on covered 2.4L",evidence:"Base timing correct but reluctor indexing wrong",firstTest:"Follow PIP4548E comparison procedure"}],freezeFrame:[...commonFreeze,"Cam desired and actual angle","Oil level/viscosity/pressure","Cam and crank circuit companion codes"],steps:[{title:"Protect the evidence and engine",detail:"Save data and stop for noise or pressure warning."},{title:"Verify oil and identity",detail:"Confirm RPO, level, viscosity and service history."},{title:"Test electrical/VVT response",detail:"Inspect circuits and graph commanded versus actual angle."},{title:"Check correlation",detail:"Use a scope or SI mechanical procedure."},{title:"Apply the 2.4L bulletin narrowly",detail:"Consider reluctor only on a matched application after timing passes."},{title:"Verify relearns and monitor",detail:"Complete required setup and repeat the setting condition."}],dontReplace:"Do not replace cam and crank sensors merely because their names appear in the definition. A sensor can report a real mechanical phase error accurately.",yearNotes:["PIP4548E covers 2010–2016 Equinox 2.4L engines among defined RPOs and warns the LE5 illustration is not universal.","Turbo engines use different actuators, timing hardware and diagnostic specifications; use VIN-correct SI."],faqs:[{question:"Can low oil cause P0016?",answer:"Yes, when VVT control loses hydraulic authority, but mechanical and electrical causes remain."},{question:"Is it always a timing chain?",answer:"No. Oil, actuator, wiring, assembly and reluctor faults can produce correlation error."},{question:"Can I drive?",answer:"Not with noise, low pressure, stalling or no-start; otherwise diagnose promptly."},{question:"Should I replace both sensors?",answer:"No. Test circuits and actual correlation first."},{question:"Can overheating matter?",answer:"GM notes it may contribute to reluctor movement on defined older engines."},{question:"What if it started after repair?",answer:"Recheck mechanical timing and indexing before ordering parts."},{question:"Is a relearn enough?",answer:"Not when an electrical, hydraulic or mechanical fault remains."},{question:"What proves repair?",answer:"Correct phase response and no pending correlation code under the original condition."}],sources:[p0016]}),
guide({slug:"p1101",code:"P1101",title:"P1101 Code Chevy Equinox: Intake Airflow and Boost Leak Tests",description:"Diagnose Equinox P1101 with intake and charge-air leak testing, MAF/MAP plausibility, PCV checks and year-specific GM hose bulletins.",definition:"Intake Air Flow System Performance",severity:"Diagnose promptly",driveAdvice:"Avoid boost and hard acceleration with reduced power, whistling, smoke or unstable fueling. Stop for severe power loss, overheating or flashing misfire.",quickAnswer:"P1101 means measured airflow did not agree with the model expected by the ECM; it is not automatically a bad MAF sensor. On turbo Equinox engines inspect the complete air path from filter through turbo, charge-air cooler and throttle, then validate MAF/MAP/boost data and PCV integrity. GM identifies a missing/damaged coupler O-ring on defined 2018 engines and a split inlet hose beneath its sleeve on defined 2023–2025 engines.",symptoms:[{key:"power",label:"Reduced power",response:"Save P0101/P0237/P0299 companions and inspect charge plumbing."},{key:"whistle",label:"Whistle or whoosh",response:"Pressure/smoke-test without assuming the visible hose is the only leak."},{key:"after",label:"After filter or turbo work",response:"Check clamps, seals, sensor orientation and disconnected hoses."},{key:"idle",label:"Rough idle",response:"Include PCV and vacuum-side leaks."},{key:"sleeve",label:"Damaged abrasion sleeve",response:"On 2023–2025 LSD, inspect the hose beneath it per PIP5927B."}],causes:[{cause:"Loose/split intake or charge pipe",evidence:"Smoke/pressure loss and abnormal airflow",firstTest:"Inspect then controlled leak test"},{cause:"Missing/damaged CAC coupler O-ring",evidence:"2018 matched engine and leak at coupler",firstTest:"Follow PIP5402C after normal SI checks"},{cause:"Inlet hose split beneath sleeve",evidence:"2023–2025 LSD sleeve damage",firstTest:"Remove/inspect per PIP5927B"},{cause:"MAF/MAP/boost sensor contamination or circuit",evidence:"Implausible PID or circuit result",firstTest:"Visual, reference/signal and plausibility tests"},{cause:"PCV/throttle/calibration issue",evidence:"No external leak and engine-specific evidence",firstTest:"Follow SI performance diagnostic"}],freezeFrame:[...commonFreeze,"MAF, MAP and desired/actual boost","Throttle angle and fuel trims","P0101/P0237/P0299 companions"],steps:[{title:"Save the airflow story",detail:"Capture all codes and simultaneous PIDs."},{title:"Identify engine and bulletin window",detail:"Separate 2018 LYX/LTG from 2023–2025 LSD."},{title:"Inspect the entire path",detail:"Check airbox through throttle plus PCV."},{title:"Smoke/pressure-test correctly",detail:"Seal the system as SI directs and inspect couplers."},{title:"Test sensors and circuits",detail:"Use reference, signal and plausibility evidence."},{title:"Verify under boost safely",detail:"Confirm commanded and actual values track without pending return."}],dontReplace:"Do not replace the MAF sensor just because P1101 contains ‘air flow.’ Leaks, seals, PCV, boost plumbing, sensor circuits and calibration can all make valid airflow data disagree with the model.",yearNotes:["2018 LYX/LTG: PIP5402C identifies a possible charge-air-cooler coupler O-ring after normal diagnosis.","2023–2025 LSD: PIP5927B identifies possible inlet-hose damage beneath the anti-abrasion sleeve.","Other years/engines require the normal SI path; neither bulletin is universal."],faqs:[{question:"Is P1101 a bad MAF sensor?",answer:"Not necessarily; it is an airflow plausibility code."},{question:"Can a boost leak cause it?",answer:"Yes, and GM documents specific hose/seal faults on defined applications."},{question:"Can I drive?",answer:"Limit load; stop for severe reduced power or misfire."},{question:"How is a leak found?",answer:"With careful inspection and controlled smoke/pressure testing."},{question:"Should I clean the MAF?",answer:"Only with an approved method after inspection; cleaning cannot repair wiring or leaks."},{question:"Why did it appear after service?",answer:"A loose clamp, seal, connector or incorrect filter/duct assembly may alter airflow."},{question:"Do both GM bulletins apply together?",answer:"No. They cover different years and engine RPOs."},{question:"What proves repair?",answer:"Airflow/boost agreement and no pending code under the original load."}],sources:[p1101old,p1101new]}),
guide({slug:"p0496",code:"P0496",title:"P0496 Code Chevy Equinox: Purge Flow Diagnostic Tests",description:"Diagnose Equinox P0496 with purge-sealing tests, fuel-tank-pressure data, hose inspection and post-refuel symptom checks before replacing parts.",definition:"Evaporative Emission System Flow During Non-Purge",severity:"Service soon",driveAdvice:"Usually safe for a short trip if it is the only code, but hard starting, stalling, strong vapor odor or a suspected liquid-fuel leak needs prompt attention. Work away from sparks and heat.",quickAnswer:"P0496 means the ECM detected EVAP vacuum or flow when purge should not be occurring. A purge valve leaking internally is common, but hose routing, electrical command, fuel-tank-pressure bias and canister contamination must be tested. A post-refuel hard start strengthens the purge hypothesis; it does not prove the valve without a sealing test.",symptoms:[{key:"refuel",label:"Hard start after refueling",response:"Test purge flow with the valve commanded closed."},{key:"idle",label:"Rough idle or stall",response:"Compare trims and isolate unintended vapor flow."},{key:"odor",label:"Fuel-vapor odor",response:"Inspect immediately for physical leakage."},{key:"fuel",label:"Fuel gauge/FTP data implausible",response:"Validate sensor and circuit before valve replacement."},{key:"none",label:"Lamp only",response:"Run commanded seal and FTP response tests."}],causes:[{cause:"Purge valve leaks closed",evidence:"Vacuum/flow persists with no command",firstTest:"Bidirectional command and physical seal test"},{cause:"Purge circuit commanded unintentionally",evidence:"Electrical command does not match request",firstTest:"Circuit voltage/control test"},{cause:"Hose routing/leak near purge",evidence:"Recent work or smoke escape",firstTest:"Compare routing and smoke-test"},{cause:"FTP sensor bias",evidence:"Pressure signal implausible key-on/vented",firstTest:"Controlled pressure and circuit test"},{cause:"Saturated/damaged canister",evidence:"Topping-off history/liquid fuel",firstTest:"Inspect canister and vent path"}],freezeFrame:[...commonFreeze,"Fuel level and FTP signal","Purge/vent commands","Refueling and topping-off history"],steps:[{title:"Save fuel and pressure context",detail:"Do not clear the evidence."},{title:"Inspect routing and connectors",detail:"Check recent service areas first."},{title:"Command purge closed",detail:"Verify it physically seals, not merely clicks."},{title:"Validate FTP response",detail:"Check vented baseline and controlled vacuum."},{title:"Inspect vent/canister",detail:"Look for liquid fuel or restriction."},{title:"Complete EVAP monitor",detail:"Verify no pending return at a valid fuel level."}],dontReplace:"Do not replace the purge valve solely because it is common. Prove flow when commanded closed and rule out control, plumbing and pressure-sensor errors.",yearNotes:["Purge plumbing, valve location and cap/capless filler hardware vary by generation and engine.","Do not claim GM Special Coverage N222369620 for an Equinox; the published coverage document identifies specific Cadillac XTS and Chevrolet Impala populations, not this model."],faqs:[{question:"Is P0496 usually the purge valve?",answer:"It is a common cause, but a sealing test is still required."},{question:"Why is it hard to start after fuel?",answer:"Unwanted vapor can over-rich the intake during restart."},{question:"Can I drive?",answer:"Usually briefly if alone; not with leakage, stalling or strong odor."},{question:"Can topping off cause problems?",answer:"Yes, liquid fuel can saturate the canister."},{question:"Will tightening the cap fix it?",answer:"P0496 is a flow fault; a cap is not the default diagnosis."},{question:"How do I test purge?",answer:"Command it closed and verify no physical flow with safe equipment."},{question:"Is there Equinox special coverage?",answer:"Do not infer it from N222369620; verify VIN programs directly with Chevrolet."},{question:"What confirms repair?",answer:"Correct FTP response and a completed EVAP monitor without pending return."}]}),
guide({slug:"p0521",code:"P0521",title:"P0521 Code Chevy Equinox: Oil Pressure Signal Diagnosis",description:"Diagnose Equinox P0521 safely with oil-level and condition checks, mechanical pressure testing, sensor circuits and GM PCV/calibration guidance.",definition:"Engine Oil Pressure Sensor Performance",severity:"Stop soon",driveAdvice:"Shut the engine off immediately for a red oil-pressure warning, ticking/knocking, or pressure near zero. Do not drive to ‘see if it clears.’ A code without those symptoms still requires the level, oil condition and actual pressure to be verified before extended operation.",quickAnswer:"P0521 means the oil-pressure signal is outside the ECM's expected performance range; it does not distinguish low mechanical pressure from a sensor, circuit, oil-quality, aeration, filter, PCV or calibration issue. Check the dipstick and warning state first, then compare scan data with a mechanical gauge using the exact engine procedure. GM 18-NA-246 provides a defined Equinox path that may include programming, PCV service and oil/filter replacement.",symptoms:[{key:"red",label:"Red oil-pressure warning",response:"Shut down immediately and verify mechanical pressure."},{key:"noise",label:"Tick or knock",response:"Do not restart repeatedly; inspect for lubrication damage."},{key:"fuel",label:"Oil level high or smells of fuel",response:"Do not assume sensor failure; diagnose dilution and PCV/fueling cause."},{key:"inter",label:"Intermittent reading",response:"Wiggle-test circuit while comparing gauge and scan data."},{key:"after",label:"After oil service",response:"Verify level, viscosity, filter and leaks before deeper repair."}],causes:[{cause:"Low/incorrect/diluted oil or wrong filter",evidence:"Dipstick/service history abnormal",firstTest:"Verify level, specification, filter and contamination"},{cause:"Sensor or connector/circuit",evidence:"Scan value disagrees with gauge or circuit test fails",firstTest:"Mechanical gauge plus voltage/ground/signal test"},{cause:"PCV/calibration condition on covered application",evidence:"VIN/build/RPO matches 18-NA-246",firstTest:"Follow bulletin sequence exactly"},{cause:"Pump pickup/relief or internal wear",evidence:"Mechanical pressure below SI minimum",firstTest:"Professional mechanical diagnosis"},{cause:"Aeration/sludge/restriction",evidence:"Pressure unstable and oil condition abnormal",firstTest:"Inspect oil/filter and lubrication path"}],freezeFrame:[...commonFreeze,"Oil-pressure PID by rpm/temperature","Dipstick level and oil condition","Filter/viscosity/service history"],steps:[{title:"Decide whether to shut down",detail:"Warning/noise means no further running."},{title:"Verify oil and service parts",detail:"Check cold level, condition, viscosity and filter."},{title:"Save scan behavior",detail:"Record pressure versus rpm and temperature."},{title:"Measure mechanical pressure",detail:"Use the exact adapter and SI limits."},{title:"Test circuit or internal system",detail:"Let gauge comparison determine the branch."},{title:"Apply bulletin and verify",detail:"Match build/RPO and confirm hot/cold pressure after repair."}],dontReplace:"Do not install an oil-pressure sensor before proving actual pressure. A new sensor cannot repair low mechanical pressure, dilution, an incorrect filter, PCV fault or calibration issue.",yearNotes:["18-NA-246 contains model-year/build-breakpoint detail; verify the complete VIN application before programming or PCV service.","Oil-pressure specifications and gauge connection points differ across 2.4L, V6, turbo gasoline and diesel engines."],faqs:[{question:"Can I drive with P0521?",answer:"Not with a pressure warning, noise or near-zero reading."},{question:"Is it usually the sensor?",answer:"It can be, but actual pressure must be proven first."},{question:"Can low oil cause it?",answer:"Yes; level and leakage are the first safe checks."},{question:"Can fuel dilution matter?",answer:"Yes, it changes viscosity and can be part of the covered GM condition."},{question:"How is pressure verified?",answer:"With a calibrated mechanical gauge and engine-specific SI limits."},{question:"Does the bulletin apply to every Equinox?",answer:"No. Match year, engine and build breakpoint."},{question:"Will an oil change fix it?",answer:"Only when the diagnosed procedure calls for it; it cannot repair internal wear."},{question:"What confirms repair?",answer:"Safe mechanical pressure and a plausible sensor signal hot and cold."}],sources:[p0521]}),
guide({slug:"p2135",code:"P2135",title:"P2135 Code Chevy Equinox: Throttle Correlation and Reduced Power",description:"Diagnose Equinox P2135 using dual throttle-position graphs, five-volt reference and wiring tests, throttle inspection and older-model GM guidance.",definition:"Throttle Position Sensor 1–2 Correlation",severity:"Diagnose promptly",driveAdvice:"Reduced Power can limit acceleration unpredictably. Move out of traffic without forcing the throttle and arrange diagnosis. Stop for surging, sticking throttle, overheating wiring or repeated stalling.",quickAnswer:"P2135 means the two throttle-position signals no longer agree within the calibrated relationship. The cause may be throttle-body sensors, connector fretting, wiring, shared reference/ground, contamination or calibration. GM's older 2007–2009 Equinox bulletin explicitly says not to replace the complete throttle body automatically on its listed V6 RPOs; newer engines use different procedures.",symptoms:[{key:"reduced",label:"Reduced Engine Power",response:"Save codes and avoid demanding acceleration."},{key:"inter",label:"Intermittent after bumps/heat",response:"Graph both TP signals while inspecting harness/terminal tension."},{key:"idle",label:"Unstable idle",response:"Inspect bore/plate only with approved procedure and test correlation."},{key:"many",label:"Several five-volt codes",response:"Find shared reference short before throttle replacement."},{key:"older",label:"2007–2009 listed V6",response:"Check bulletin 12-06-04-003A before ordering the assembly."}],causes:[{cause:"Throttle-position sensor disagreement",evidence:"TP1/TP2 relationship breaks",firstTest:"Graph both signals through controlled sweep"},{cause:"Connector/terminal or harness fault",evidence:"Dropout with movement/heat",firstTest:"Terminal, pin-fit and circuit load tests"},{cause:"Shared five-volt reference/ground fault",evidence:"Multiple sensor codes",firstTest:"Isolate shared branches"},{cause:"Throttle contamination/binding",evidence:"Plate movement abnormal and inspection supports it",firstTest:"Follow approved cleaning/inspection method"},{cause:"Calibration or older serviceable cover condition",evidence:"Matched bulletin/application",firstTest:"Follow VIN-specific GM procedure"}],freezeFrame:[...commonFreeze,"TP sensor 1 and 2 voltage/percent","Commanded and actual throttle angle","Accelerator-pedal PIDs and five-volt companion codes"],steps:[{title:"Save Reduced Power evidence",detail:"Record current/history status before key cycling."},{title:"Identify year and engine",detail:"Determine whether the older bulletin applies."},{title:"Graph both TP signals",detail:"Look for disagreement/dropout, not just final values."},{title:"Inspect and load-test circuits",detail:"Check pin fit, reference, ground and signal integrity."},{title:"Inspect throttle safely",detail:"Follow SI; keep fingers out of an energized electronic throttle."},{title:"Complete setup and road verification",detail:"Perform required relearn/programming and confirm smooth correlation."}],dontReplace:"Do not automatically replace the throttle body. The older GM bulletin says exactly that for covered Equinox V6 applications, and newer vehicles still require circuit and correlation evidence.",yearNotes:["12-06-04-003A covers 2007–2009 Equinox with listed V6 RPOs and a specific throttle-position sensor-cover procedure.","Later 2.4L and turbo engines do not inherit that repair; use their VIN-specific SI tests and parts strategy."],faqs:[{question:"Can I drive with P2135?",answer:"Avoid normal driving because reduced-power response can be unpredictable."},{question:"Does it mean a bad throttle body?",answer:"No. Wiring, terminals, reference voltage and calibration can cause it."},{question:"Why are there two sensors?",answer:"The ECM compares redundant signals to detect unsafe disagreement."},{question:"Can cleaning fix it?",answer:"Only when approved inspection proves contamination/binding; cleaning cannot repair electronics."},{question:"Can a battery reset fix it?",answer:"It may clear symptoms temporarily but does not repair the cause."},{question:"Does the 2007–2009 bulletin apply to newer cars?",answer:"No. It is limited to listed years and V6 RPOs."},{question:"Is a relearn required?",answer:"Follow VIN-specific SI after repair; requirements vary."},{question:"What confirms repair?",answer:"Smooth correlated TP signals and no pending fault through the original condition."}],sources:[p2135]}),
guide({slug:"p0455",code:"P0455",title:"P0455 Code Chevy Equinox: Large EVAP Leak Diagnosis",description:"Find Equinox P0455 with cap or filler checks, regulated smoke, purge and vent commands, fuel-tank-pressure testing and safe leak inspection.",definition:"Evaporative Emission System Large Leak Detected",severity:"Service soon",driveAdvice:"Usually safe briefly when it is the only symptom, but do not drive with liquid fuel leakage, a powerful vapor odor, stalling or tank damage. Keep all ignition sources away from EVAP testing.",quickAnswer:"P0455 means the EVAP system could not hold the expected vacuum/pressure and interpreted the loss as a gross leak. The code does not locate it. A loose/missing cap where equipped, capless filler fault, disconnected hose, vent or purge valve stuck open, cracked canister and tank/module seals require systematic testing.",symptoms:[{key:"after",label:"Appeared after refueling",response:"Inspect cap/filler seal and disturbed area first."},{key:"odor",label:"Strong vapor smell",response:"Inspect promptly for an actual leak."},{key:"hard",label:"Hard start after fuel",response:"Test purge sealing as well as leak integrity."},{key:"fill",label:"Tank difficult to fill",response:"Inspect vent path and canister restriction."},{key:"none",label:"Lamp only",response:"Run regulated smoke with commanded valves."}],causes:[{cause:"Loose/missing cap or filler seal",evidence:"Visible sealing fault",firstTest:"Inspect correct cap/capless flap and neck"},{cause:"Disconnected/cracked EVAP hose",evidence:"Smoke escapes at line/connector",firstTest:"Low-pressure smoke test"},{cause:"Vent valve cannot close",evidence:"Fails bidirectional seal/circuit test",firstTest:"Command and verify physical sealing"},{cause:"Purge valve stuck open",evidence:"Flow while commanded closed",firstTest:"Purge seal test"},{cause:"Canister, tank or module seal damage",evidence:"Smoke/liquid-fuel evidence",firstTest:"Inspect exact tank configuration"}],freezeFrame:[...commonFreeze,"Fuel level and FTP signal","Purge/vent commands","Refuel timing and filler type"],steps:[{title:"Save enable conditions",detail:"Fuel level and temperature matter."},{title:"Inspect filler and visible hoses",detail:"Correct obvious openings without disturbing evidence."},{title:"Use regulated smoke",detail:"Never apply shop-air pressure directly."},{title:"Command purge and vent",detail:"Verify physical movement/sealing and circuits."},{title:"Validate FTP response",detail:"Confirm the sensor reports controlled changes."},{title:"Run the monitor",detail:"Allow proper soak/fuel window and check pending status."}],dontReplace:"Do not call every P0455 a gas cap. A valve held open can look like a large leak, and capless Equinox applications require a different filler inspection.",yearNotes:["Conventional-cap and capless systems, vent placement and tank hardware vary across Equinox generations.","No universal Equinox purge-valve special coverage was found; verify VIN programs directly rather than extrapolating another GM model's coverage."],faqs:[{question:"Is P0455 always the gas cap?",answer:"No. Hoses, purge, vent, canister and tank seals can cause it."},{question:"Can I drive?",answer:"Usually briefly if alone; not with liquid leakage or strong vapor symptoms."},{question:"Can purge cause it?",answer:"Yes, when the valve cannot seal."},{question:"How is the leak found?",answer:"With regulated smoke and commanded purge/vent testing."},{question:"Can topping off matter?",answer:"Yes, liquid fuel can damage or saturate the canister."},{question:"Why will the monitor not run?",answer:"Fuel level, soak and temperature may be outside enable limits."},{question:"Should I buy a cap first?",answer:"Inspect it first where fitted; do not substitute parts for testing."},{question:"What proves repair?",answer:"The system seals and the EVAP monitor completes without pending return."}]}),
guide({slug:"p0442",code:"P0442",title:"P0442 Code Chevy Equinox: Small EVAP Leak Testing",description:"Locate Equinox P0442 small EVAP leaks using filler inspection, low-pressure smoke, purge and vent sealing tests and fuel-tank-pressure data.",definition:"Evaporative Emission System Small Leak Detected",severity:"Service soon",driveAdvice:"Normally safe for limited driving if alone, but investigate fuel odor, liquid leakage, stalling or post-refuel hard starting promptly. EVAP work requires ventilation and freedom from sparks/flames.",quickAnswer:"P0442 means the EVAP monitor detected leakage below the gross-leak threshold. It does not identify the leak location. Small cap/filler seal defects, hairline hose cracks, connector O-rings, purge seepage, incomplete vent sealing, canister seams and tank/module seals often require a patient low-pressure smoke test.",symptoms:[{key:"only",label:"Lamp only",response:"Use low-pressure smoke and valve commands."},{key:"refuel",label:"After refueling",response:"Inspect filler sealing and purge behavior."},{key:"odor",label:"Occasional odor",response:"Check flex lines and seams under the same temperature."},{key:"inter",label:"Intermittent",response:"Preserve ambient/fuel-level context before clearing."},{key:"codes",label:"P0496 also present",response:"Test purge leakage with valve commanded closed."}],causes:[{cause:"Cap/capless filler sealing defect",evidence:"Seal or flap fault",firstTest:"Inspect without immediately disturbing"},{cause:"Tiny hose or connector leak",evidence:"Fine smoke at seam/O-ring",firstTest:"Patient regulated smoke test"},{cause:"Purge valve seepage",evidence:"Small flow when closed",firstTest:"Physical seal test"},{cause:"Vent valve incomplete sealing",evidence:"Commanded closed but pressure decays",firstTest:"Valve/circuit and contamination test"},{cause:"Canister/tank/module seal or FTP bias",evidence:"Smoke/implausible response",firstTest:"Inspect and validate sensor"}],freezeFrame:[...commonFreeze,"Fuel level and FTP","Ambient/soak duration","Purge and vent command states"],steps:[{title:"Preserve the monitor context",detail:"Record fuel level and ambient state."},{title:"Inspect filler carefully",detail:"Document seal before moving it."},{title:"Smoke at regulated low pressure",detail:"Watch all seams and quick connects patiently."},{title:"Command both valves",detail:"A click does not prove sealing."},{title:"Validate FTP",detail:"Check vented baseline and controlled response."},{title:"Complete the monitor",detail:"Recheck pending code after valid enable conditions."}],dontReplace:"Do not repeatedly replace the cap. Small leaks often hide at an O-ring, hose seam or valve seat and need a controlled test.",yearNotes:["Small-leak monitor thresholds and enable conditions change by model year and calibration.","Capless and conventional filler systems require different inspection methods; identify the vehicle hardware first."],faqs:[{question:"Can I drive with P0442?",answer:"Usually briefly if alone; not with liquid fuel or strong odor."},{question:"Is it a gas cap?",answer:"It can be, but many small paths produce the same code."},{question:"Can purge cause it?",answer:"Yes, slight leakage when commanded closed can fail the monitor."},{question:"Why is it intermittent?",answer:"Temperature, fuel level and hose movement can open tiny leaks."},{question:"How is it found?",answer:"Regulated low-pressure smoke plus valve and FTP tests."},{question:"Will clearing help?",answer:"No. It erases useful enable data and resets readiness."},{question:"Is it an urgent engine problem?",answer:"Usually not alone, but fuel leakage and vapor odor change the urgency."},{question:"What proves repair?",answer:"No measured leak and a completed EVAP monitor without pending return."}]}),
];
